__NUXT_JSONP__("/rumbo-democratico/publicaciones/radar_ethos_2023", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{post:{slug:"radar_ethos_2023",title:i,date:"2023-04-28T16:53:53.337Z",img:"https:\u002F\u002Fucarecdn.com\u002F6e21ba10-d2d8-4a69-be6c-20a6ecb1ebe0\u002F","img-alt":i,autor:k,category:c,extracto:"En su inicio, el Poder Ejecutivo planteaba una serie de modificaciones que darían como resultado un país más justo, equitativo, con finanzas públicas sanas y menos corrupción. Sin embargo, la esperanza de un cambio se ha ido diluyendo pues la realidad nos muestra que aún hay mucho por hacer para lograr estos objetivos.",file:"https:\u002F\u002Fucarecdn.com\u002Fdd72c5c5-78a9-4aaf-9866-0eaf6e89665e\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"A más de cuatro años del inicio de la administración federal, aún existen problemas endémicos y preocupaciones sobre el rumbo que lleva México en materia de desarrollo sostenible, pobreza, combate a la corrupción, finanzas públicas y transición energética."},{type:b,tag:f,props:{},children:[]},{type:a,value:l},{type:b,tag:f,props:{},children:[]},{type:a,value:"\nNos preocupa que estos desafíos se mantienen latentes y, tarde o temprano, se observarán sus manifestaciones más nocivas si no los atendemos a la brevedad. Por eso hoy presentamos "},{type:b,tag:"strong",props:{},children:[{type:a,value:i}]},{type:a,value:", un documento de análisis en el que exponemos cuáles son esos pendientes. "},{type:b,tag:f,props:{},children:[]},{type:a,value:l},{type:b,tag:f,props:{},children:[]},{type:a,value:"\nHacemos un urgente llamado a la reflexión y a la acción para ver estos temas que requieren de nuestra atención. Sabemos que si trabajamos unidos como sociedad, podremos lograr un México más próspero."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fradar_ethos_2023",extension:h,createdAt:j,updatedAt:j},publicaciones:[{slug:"analisis_de_las_propuestas_de_claudia_sheinbaum_en_materia_de_anticorrupcion_finanzas_publicas_adaptacion_al_cambio_climatico_y_politica_de_cuidados",title:m,date:"2024-08-06T21:44:32.127Z",img:"https:\u002F\u002Fucarecdn.com\u002F2b417d06-8f0a-4ec5-974f-ff6ea055dd26\u002F","img-alt":m,autor:k,category:c,extracto:"En Ethos Innovación en Políticas Públicas nos dimos a la tarea de analizar las propuestas de la próxima presidenta en materia de combate a la corrupción, finanzas públicas, adaptación al cambio climático y políticas de cuidados.",file:"https:\u002F\u002Fucarecdn.com\u002Fb3e060fb-9374-4c9a-a83c-6cd0c917f2dc\u002F",tags:[],toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"Ante el próximo cambio de gobierno, es primordial contrastar la realidad que enfrenta el país con las propuestas que presentó Claudia Sheinbaum durante su campaña presidencial. En ese sentido, en Ethos Innovación en Políticas Públicas nos dimos a la tarea de analizar las propuestas de la próxima presidenta en materia de combate a la corrupción, finanzas públicas, adaptación al cambio climático y políticas de cuidados"}]}]},dir:g,path:"\u002Fpublicaciones\u002Fanalisis_de_las_propuestas_de_claudia_sheinbaum_en_materia_de_anticorrupcion_finanzas_publicas_adaptacion_al_cambio_climatico_y_politica_de_cuidados",extension:h,createdAt:n,updatedAt:n},{slug:"manual_de_buenas_practicas_para_la_apertura_de_datos_abiertos",title:"Manual de buenas prácticas para la apertura de datos abiertos",date:"2025-07-30T18:06:18.941Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffdb260da-1a3a-4b40-8237-ebe3ec935e42\u002F","img-alt":"Datos abiertos",autor:"Dalia Toledo y Teresa López Barajas",category:c,extracto:o,file:"https:\u002F\u002Fucarecdn.com\u002Ffd8056dd-6c4a-4c08-abc5-4db9edfcdc93\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:o}]}]},dir:g,path:"\u002Fpublicaciones\u002Fmanual_de_buenas_practicas_para_la_apertura_de_datos_abiertos",extension:h,createdAt:p,updatedAt:p},{slug:"polarizacion_politica_un_fenomeno_que_vuelve_a_ser_tendencia",title:q,date:"2023-05-29T20:50:02.445Z",img:"https:\u002F\u002Fucarecdn.com\u002F6b405cef-c423-4b38-b1e0-3ef3e39a27dc\u002F","img-alt":q,autor:"Javier González",category:c,extracto:"En los últimos años América Latina ha experimentado un incremento en la polarización1 política. El malestar social, las contiendas electorales reñidas y el estancamiento legislativo a menudo se atribuyen a los altos niveles de polarización.",file:"https:\u002F\u002Fucarecdn.com\u002F596e220d-21ae-4a43-ae48-d36f3dc2e4a4\u002F",toc:[],body:{type:d,children:[{type:b,tag:e,props:{},children:[{type:a,value:"En los últimos años América Latina ha experimentado un incremento en la polarización1 política. El malestar social, las contiendas electorales reñidas y el estancamiento legislativo a menudo se atribuyen a los altos niveles de polarización."}]}]},dir:g,path:"\u002Fpublicaciones\u002Fpolarizacion_politica_un_fenomeno_que_vuelve_a_ser_tendencia",extension:h,createdAt:"2023-10-11T18:18:44.378Z",updatedAt:j}]}],fetch:{},mutations:[]}}("text","element","rumbo-democratico","root","p","br","\u002Fpublicaciones",".md","Radar Ethos 2023","2023-10-11T18:18:44.379Z","Ethos","\n","Análisis de las propuestas de Claudia Sheinbaum en materia de anticorrupción, finanzas públicas, adaptación al cambio climático y política de cuidados","2024-10-02T22:32:44.108Z","Este manual tiene como propósito ofrecer una guía práctica y accesible para los servidores públicos que participan en los procesos de apertura de sus instituciones, ya que a través de conceptos clave, recomendaciones puntuales y buenas prácticas documentadas, buscamos fortalecer las capacidades institucionales para garantizar que los datos que se abren cumplan con los principios de calidad, utilidad, accesibilidad y sostenibilidad.","2025-11-25T01:24:03.297Z","Polarización política: un fenómeno que vuelve a ser tendencia")));